// This node builds the search sentence for Qdrant
// Synchronized with our clean input normalizer payload schema
const archetype = $json.problem_archetype;
const drivers = $json.drivers || [];

// Create a clean list of human descriptions, falling back to the feature name if "N/A"
const causePhrases = drivers
    .map(d => (d.description && d.description !== "N/A") ? d.description : d.feature)
    .join(', ');

return {
    // This is the "Semantic Query" optimized for the embedding engine
    rag_query: `Standard operating procedure for ${archetype} issues, specifically addressing ${causePhrases}.`,

    // Pass everything else through completely intact (mapped_domain, order_details, drivers, etc.)
    ...$json 
};

// In 'Run once for each item' mode, n8n automatically unpacks the item into $json
const data = $json.body ? $json.body : $json;

// Check for core operational parameters to prevent execution drops
if (!data || !data.order_id) {
    throw new Error("SOP Retrieval Subflow Error: Missing core order data package.");
}

// Pass forward the clean data structures, capturing the new symbolic anchor domain
return {
    order_id: data.order_id,
    problem_archetype: data.problem_archetype,
    archetype_description: data.archetype_description,
    mapped_domain: data.mapped_domain, // Driven forward for Qdrant metadata filtering
    order_details: data.order_details,

    // FIX: Read 'source_drivers' if 'drivers' is blank, ensuring the array is never lost
    drivers: data.drivers || data.source_drivers || [],

    // ─── STATE ARRAYS: Carry tracking telemetry forward safely ───
    audit_round: data.audit_round || 1,
    is_reflection: data.is_reflection || false,
    rejection_reasons_log: data.rejection_reasons_log || ""
};

// 1. In 'Run once for each item' mode, the raw response from Qdrant is already unpacked into $json
const qdrantResults = $json.result || [];

// 2. Extract and join the text from each chunk's payload dynamically
const combinedSOPs = qdrantResults.map((hit, index) => {
  const textContent = hit.payload && hit.payload.text ? hit.payload.text : "No policy text found.";
  const sourceFile = hit.payload && hit.payload.source ? hit.payload.source : "SOP Document v1.1";
  return `[SOP Source ${index + 1} | File: ${sourceFile}]:\n${textContent}`; 
}).join('\n\n');

// FALLBACK PROTECTION: If Qdrant returns 0 hits, prevent the downstream agent from hallucinating rules
const safeSOPContext = combinedSOPs.trim() ? combinedSOPs : "CRITICAL WARNING: No matching corporate governance clauses found in database for this domain. Fallback strictly to manual human operator escalation.";

// 3. FIXED: Pull the original data suitcase from the entry node of this subflow
// This guarantees we get our pristine incoming variables back, independent of Qdrant's output structure.
const originalData = $('SOP_Normalize_Input').item.json;

// 4. Return the Final "Agent-Ready" comprehensive data envelope
return {
  order_id: originalData.order_id,
  problem_archetype: originalData.problem_archetype,
  mapped_domain: originalData.mapped_domain, // Carried forward to justify choices to the Evaluator Agent
  sop_context: safeSOPContext,                // Pure, clean, parsed text for the Planner Agent to read
  order_details: originalData.order_details,  // Full semantic suitcase intact

  // DOUBLE-CHECK ALIGNMENT: Defensively catch both names to ensure drivers are never wiped out
  drivers: originalData.drivers || originalData.source_drivers || [],        

  // ─── STATE ARRAYS: Forward telemetry suitcase variables cleanly back to the main canvas workflow ───
  audit_round: originalData.audit_round || 1,
  is_reflection: originalData.is_reflection || false,
  rejection_reasons_log: originalData.rejection_reasons_log || ""
};
